```go
package main

import (
	"fmt"
	"os"

	"github.com/avast/retry-go"
	"golang.org/x/tools/go/packages"
)

// Define the function to convert Go struct to Avro schema
func genAvroSchema(srcFileName string) error {
	// Get the source package info
	pkgs := packages.New()
	err := pkgs.Load(srcFileName)
	if err != nil {
		return fmt.Errorf("failed to load %s: %v", srcFileName, err)
	}

	// Parse the struct
	structDef, err := pkgs.ParseStruct("MyStruct")
	if err != nil {
		return fmt.Errorf("failed to parse struct %s: %v", "MyStruct", err)
	}

	// Generate the Avro schema
	schema, err := structDef.GenerateSchema(0)
	if err != nil {
		return fmt.Errorf("failed to generate Avro schema for %s: %v", "MyStruct", err)
	}

	// Write the Avro schema to a file
	file, err := os.Create(fmt.Sprintf("%s.avsc", "struct"))
	if err != nil {
		return fmt.Errorf("failed to create file: %v", err)
	}
	defer file.Close()

	_, err = file.WriteString(schema.String())
	if err != nil {
		return fmt.Errorf("failed to write to file: %v", err)
	}

	return nil
}

func main() {
	srcFileName := "path/to/your/source/file.go" // Replace with your actual source file path
	err := genAvroSchema(srcFileName)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		os.Exit(1)
	}
	fmt.Println("AVRO Schema generated successfully.")
}
```

